"""ORACLE-119: full installer for the consolidated atomic worker.

Installs one standalone trading worker, deterministic tests and a CMD launcher.
Does not edit or restart existing scanners. Never reads or writes wallet secrets.
Only the explicitly invoked runtime can access keys already present in the CMD environment.
"""
from __future__ import annotations
from pathlib import Path
import subprocess
