LAUNCHER = "\"\"\"Run the single ORACLE-119 worker without echoing credentials.\"\"\"\nfrom __future__ import annotations\nimport argparse\nimport getpass\nimport os\nimport shutil\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nROOT = HERE.parents[3]\nWORKER = HERE / 'oracle119_atomic_machine.cjs'\n\n\ndef main() -> int:\n    ap = argparse.ArgumentParser(description='ORACLE-119 single atomic money-path worker')\n    modes = ap.add_mutually_exclusive_group(required=True)\n    modes.add_argument('--watch', action='store_true', help='Read-only unsigned atomic simulations')\n    modes.add_argument('--trade', action='store_true', help='Enable guarded live 0.010-SOL canary')\n    ap.add_argument('--once', action='store_true', help='Check one bounded candidate batch')\n    a = ap.parse_args()\n    if not WORKER.is_file():\n        print('[HOLD] ORACLE-119 worker not installed')\n        return 2\n    if not shutil.which('node'):\n        print('[HOLD] Node.js not on PATH')\n        return 2\n    e = os.environ.copy()\n    if a.trade and not e.get('QSB_SOLANA_PRIVATE_KEY'):\n        print('[HOLD] QSB_SOLANA_PRIVATE_KEY missing in this CMD environment; no key requested or printed')\n        return 2\n    if not e.get('SOLANA_RPC_URL', '').startswith('https://'):\n        key = getpass.getpass('Helius API key (hidden): ').strip()\n        if not key:\n            print('[HOLD] Helius API key required')\n            return 2\n        e['SOLANA_RPC_URL'] = 'https://mainnet.helius-rpc.com/?api-key=' + key\n    cmd = ['node', str(WORKER), '--trade' if a.trade else '--watch']\n    if a.once:\n        cmd.append('--once')\n    return subprocess.call(cmd, cwd=str(ROOT), env=e)\n\n\nif __name__ == '__main__':\n    sys.exit(main())\n"


def main() -> None:
    if not DEST.is_dir() or not (DEST/'package.json').is_file():
        raise SystemExit('[HOLD] Existing ORACLE-105 official SDK worker and package.json required; no scanner changes')
    if not shutil.which('node'):
        raise SystemExit('[HOLD] Node.js not installed or not on PATH')
    files = {
        'oracle119_atomic_machine.cjs': WORKER,
        'oracle119_atomic_machine.test.cjs': TESTS,
        'run_oracle119.py': LAUNCHER,
    }
    original = {}
    for name, content in files.items():
        p = DEST / name
        if p.exists() and (not p.is_file() or p.is_symlink()):
            raise SystemExit('[HOLD] Unsafe installer target: ' + name)
        original[name] = p.read_bytes() if p.exists() else None
    try:
        for name, content in files.items():
            p = DEST / name
            tmp = DEST / (name+'.oracle119.tmp')
            tmp.write_text(content, encoding='utf-8', newline='\n')
            tmp.replace(p)
        for name in ('oracle119_atomic_machine.cjs','oracle119_atomic_machine.test.cjs'):
            subprocess.run(['node','--check',str(DEST / name)],check=True)
        compile(LAUNCHER, 'run_oracle119.py', 'exec')
        subprocess.run(['node',str(DEST / 'oracle119_atomic_machine.test.cjs')],check=True)
    except Exception as exc:
        for name,old in original.items():
            p=DEST/name
            if old is None:
                if p.exists(): p.unlink()
            else:
                p.write_bytes(old)
        raise SystemExit('[FAILED / RESTORED] '+type(exc).__name__+': '+str(exc))
    print('[INSTALLED] ORACLE-119 single atomic executor worker')
    print('[SCANNER] UNCHANGED [PRIVATE_KEY] NOT_USED_BY_INSTALLER')
    print('[MODES] --watch = unsigned simulations; --trade = strict profitable signed sim then single atomic 0.010-SOL canary')

if __name__ == '__main__':
    main()
